.hero-container {
    position: relative;
    width: 100%;
    overflow: hidden;
}

.hero-slider {
    display: flex;
    transition: transform 0.5s ease-in-out;
}

.hero {
    min-width: 100%;
    background-size: cover;
    background-position: bottom;
    height: 600px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    color: white;
    position: relative;
    padding: 20px;
    overflow: hidden;
}

    .hero::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background: rgba(0, 0, 0, 0.1); /* Lớp phủ đen nhạt hơn */
        transition: background 0.3s; /* Smooth transition */
    }

    .hero:hover::before {
        background: rgba(0, 0, 0, 0.5); /* Lớp phủ đen nhạt hơn khi hover */
    }

    .hero h1,
    .hero p,
    .hero button {
        opacity: 0;
        transform: translateY(20px);
        transition: opacity 0.6s ease, transform 0.6s ease;
        z-index: 1;
    }

    .hero:hover h1,
    .hero:hover p,
    .hero:hover button {
        opacity: 1;
        transform: translateY(0);
    }

    .hero h1 {
        font-size: 60px;
        text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.7);
    }

    .hero p {
        font-size: 24px;
        margin-top: 20px;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.7);
    }

    .hero button {
        margin-top: 30px;
        padding: 15px 40px;
        background-color: #add8e6;
        color: white;
        border: none;
        font-size: 18px;
        font-weight: bold;
        border-radius: 5px;
        cursor: pointer;
        transition: background-color 0.3s, transform 0.3s;
    }

        .hero button:hover {
            background-color: #7ec0ee;
            transform: scale(1.05);
        }

.features {
    display: flex;
    justify-content: space-around;
    padding: 50px 20px;
    background-color: #fff;
    text-align: center;
    flex-wrap: wrap;
}

.feature {
    max-width: 300px;
    margin: 10px;
    transition: transform 0.3s, box-shadow 0.3s;
}

    .feature:hover {
        transform: translateY(-5px);
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
    }

    .feature i {
        font-size: 50px;
        color: #5BB2F1;
        margin-bottom: 15px;
    }

    .feature h3 {
        font-size: 24px;
        margin-bottom: 10px;
        color: #333;
    }

    .feature p {
        color: #666;
    }

.about {
    padding: 50px;
    background-color: white;
    text-align: center;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    margin: 20px auto;
    max-width: 800px;
    border-radius: 10px;
}

    .about h2 {
        font-size: 36px;
        margin-bottom: 20px;
        color: #333;
    }

    .about p {
        font-size: 18px;
        line-height: 1.6;
        color: #666;
    }

.back-to-top {
    position: fixed;
    bottom: 20px;
    right: 20px;
    background: #5BB2F1;
    color: white;
    border: none;
    border-radius: 50%;
    width: 50px;
    height: 50px;
    cursor: pointer;
    display: none;
    transition: background-color 0.3s;
}

    .back-to-top:hover {
        background: #4A9ED4;
    }

.auth-link:hover {
    color: #4A9ED4;
}

/* Navigation Buttons */
.nav-buttons {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 100%;
    display: flex;
    justify-content: space-between;
    pointer-events: none;
}

.nav-button {
    background-color: rgba(0, 0, 0, 0.5);
    border: none;
    color: white;
    padding: 10px 20px;
    cursor: pointer;
    pointer-events: auto;
    font-size: 18px;
    border-radius: 5px;
    transition: background-color 0.3s, transform 0.3s;
}

    .nav-button:hover {
        background-color: rgba(0, 0, 0, 0.8);
        transform: scale(1.1);
    }

    .nav-button:focus {
        outline: none;
    }

/* Featured Services Section */
.featured-service {
    position: relative;
    width: 100%;
    overflow: hidden;
}

.service-slider {
    display: flex;
    transition: transform 0.5s ease-in-out;
}

.service {
    min-width: 100%;
    background-size: cover;
    background-position: center;
    height: 620px;
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
    overflow: hidden;
}

.service-content {
    text-align: center;
    color: white;
    opacity: 0; /* Ẩn nội dung ban đầu */
    transition: opacity 0.3s ease; /* Hiệu ứng chuyển tiếp */
}

.service:hover .service-content {
    opacity: 1; /* Hiện nội dung khi hover */
}

.service h1 {
    font-size: 40px;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.7);
}

.service p {
    font-size: 18px;
    margin-top: 20px;
    text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.7);
}

.service button {
    margin-top: 30px;
    padding: 10px 30px;
    background-color: #add8e6;
    color: white;
    border: none;
    font-size: 16px;
    font-weight: bold;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s, transform 0.3s;
}

    .service button:hover {
        background-color: #7ec0ee;
        transform: scale(1.05);
    }

