    inset-block-start: 0;
    z-index: 102;
    transition: all 0.05s ease-in-out;
    cursor: pointer;
    padding: 0.3125rem;
    margin-block-start: 0.375rem;
    margin-block-end: 0;
    margin-inline-start: 0.5rem;
    margin-inline-end: 0;
}

