        vertical-align: middle;
    }

    .animated-arrow span {
        cursor: pointer;
        height: 0.075rem;
        width: 0.75rem;
        background: var(--text-muted);
        position: absolute;
        display: block;
        content: "";
        transition: all 0.05s ease-in-out;
    }

        .animated-arrow span:before,
        .animated-arrow span:after {
            transition: all 0.05s ease-in-out;
        }

        .animated-arrow span:before {
            inset-block-start: -0.375rem;
            width: 1.4375rem;
        }

        .animated-arrow span:after {
            bottom: -0.375rem;
            width: 15px;
        }

        .animated-arrow span:before,
        .animated-arrow span:after {
            cursor: pointer;
            height: 0.075rem;
            width: 1rem;
            background: var(--text-muted);
            position: absolute;
            display: block;
            content: "";
        }
