    }

    .modal.effect-flip-horizontal.show .modal-dialog {
        transform: rotateY(0deg);
        opacity: 1;
    }

.modal.effect-flip-vertical {
    perspective: 1300px;
}

    .modal.effect-flip-vertical .modal-dialog {
